/**
 * The launch nutrition content and its lookups.
 *
 * The nutrition data is generated by the nutrition importer into
 * `nutrition.generated.json` and parsed with its schema at import, so malformed data fails
 * at startup. The lookups resolve a dish and optional variant to the profile the game
 * shows.
 */
import generatedNutrition from "./nutrition.generated.json";
import { nutritionContentSchema } from "./schemas";
import type {
  NutritionContent,
  NutritionIntentDefinition,
  NutritionIntentId,
  NutritionProfile,
  NutritionVariant,
  NutritionVariantFamily,
} from "./types";

/** The parsed nutrition profiles, variant families and intents. */
export const NUTRITION_CONTENT: NutritionContent =
  nutritionContentSchema.parse(generatedNutrition);

/**
 * Tells whether a nutrition profile is its dish's primary profile, the one served when
 * the dish has no variant family.
 *
 * @param profile - The profile to test.
 * @returns True when the profile's ID is its dish's ID.
 */
export const is_primary_profile = (
  profile: Pick<NutritionProfile, "id" | "dishId">,
): boolean => profile.id === profile.dishId;

const profileById = new Map(
  NUTRITION_CONTENT.profiles.map((profile) => [profile.id, profile]),
);
const primaryProfileByDishId = new Map(
  NUTRITION_CONTENT.profiles
    .filter(is_primary_profile)
    .map((profile) => [profile.dishId, profile]),
);
const variantFamilyByDishId = new Map(
  NUTRITION_CONTENT.variantFamilies.map((family) => [family.dishId, family]),
);
const intentById = new Map(
  NUTRITION_CONTENT.intents.map((intent) => [intent.id, intent]),
);

/**
 * Finds the variant family of a dish.
 *
 * @param dishId - The dish's content ID.
 * @returns The dish's variant family, or undefined when the dish has none.
 */
export const getNutritionVariantFamily = (
  dishId: string,
): NutritionVariantFamily | undefined => variantFamilyByDishId.get(dishId);

/**
 * Finds a variant of a dish.
 *
 * @param dishId - The dish's content ID.
 * @param variantId - The variant to find; the family's default variant when omitted.
 * @returns The variant, or undefined when the dish has no family or no such variant.
 */
export const getNutritionVariant = (
  dishId: string,
  variantId?: string,
): NutritionVariant | undefined => {
  const family = getNutritionVariantFamily(dishId);
  if (!family) return undefined;
  const resolvedVariantId = variantId ?? family.defaultVariantId;
  return family.variants.find((variant) => variant.id === resolvedVariantId);
};

/**
 * Finds the nutrition profile served for a dish and optional variant.
 *
 * A dish with a variant family resolves through the variant; one without falls back to
 * its primary profile.
 *
 * @param dishId - The dish's content ID.
 * @param variantId - The variant served; the family's default variant when omitted.
 * @returns The profile, or undefined when none matches.
 */
export const getNutritionProfile = (
  dishId: string,
  variantId?: string,
): NutritionProfile | undefined => {
  const variant = getNutritionVariant(dishId, variantId);
  if (variant) return profileById.get(variant.profileId);
  return primaryProfileByDishId.get(dishId);
};

/**
 * Finds a nutrition intent by ID.
 *
 * @param intentId - The intent's ID.
 * @returns The intent, or undefined when it is not defined.
 */
export const getNutritionIntent = (
  intentId: NutritionIntentId,
): NutritionIntentDefinition | undefined => intentById.get(intentId);
